tools.example:
S = sparameters('passive.s2p');
fprintf('%d ports, %d frequency points, Z0 = %g ohm\n', ...
    S.NumPorts, numel(S.Frequencies), S.Impedance);
s21 = rfparam(S, 2, 1);
plot(S.Frequencies/1e9, 20*log10(abs(s21)))
xlabel('GHz'); ylabel('|S_{21}| (dB)'); grid on

S = sparameters('passive.s2p');
h = smithplot(S, 1, 1, 'GridType', 'ZY', 'LineWidth', 2);
h.TitleTop = 'Input reflection';
z = gamma2z(rfparam(S, 1, 1), 50);
fprintf('Z at the first point: %.1f %+.1fj ohm\n', real(z(1)), imag(z(1)));

S = sparameters('passive.s2p');
Y = s2y(S.Parameters, S.Impedance);
Z = s2z(S.Parameters, S.Impedance);
fprintf('Y11 at f(1): %.4g %+.4gj S\n', real(Y(1,1,1)), imag(Y(1,1,1)));
Cshunt = imag(Y(1,1,:)) ./ (2*pi*reshape(S.Frequencies, 1, 1, []));

S = sparameters('passive.s2p');
Z = s2z(S.Parameters, 50);
f = S.Frequencies;
Zin = squeeze(Z(1,1,:));
plot(f/1e9, real(Zin), f/1e9, imag(Zin))
legend('R', 'X'); xlabel('GHz'); ylabel('Ohm')

S = sparameters('passive.s2p');
s21 = rfparam(S, 2, 1);
fit = rationalfit(S.Frequencies, s21, -50, 'NPoles', [4 24]);
fprintf('%d poles, error %.1f dB\n', numel(fit.A), 20*log10(fit.ErrDB));
resp = freqresp(fit, S.Frequencies);
plot(S.Frequencies/1e9, 20*log10(abs([s21 resp])))
legend('data','rational fit')

a1 = amplifier('Name', 'LNA', 'Gain', 15, 'NF', 1.2, 'OIP3', 25);
f1 = rffilter('ResponseType', 'Bandpass', 'FilterOrder', 5, ...
    'PassbandFrequency', [2.3e9 2.5e9], 'Implementation', 'Butterworth');
a2 = amplifier('Name', 'IFamp', 'Gain', 20, 'NF', 4, 'OIP3', 30);
rfb = rfbudget([a1 f1 a2], 2.4e9, -80, 20e6);
show(rfb)
fprintf('Cascade gain %.1f dB, NF %.2f dB\n', ...
    rfb.OutputPower - rfb.InputPower, rfb.NF);

ckt = circuit('lmatch');
add(ckt, [1 2], inductor(8.2e-9));
add(ckt, [2 0], capacitor(1.5e-12));
add(ckt, [2 3], resistor(50));
setports(ckt, [1 0], [3 0]);
freq = linspace(1e9, 4e9, 401);
S = sparameters(ckt, freq);
rfplot(S, 1, 1)
grid on

amp = rfckt.amplifier('NetworkData', read(rfdata.data, 'default.s2p'));
tline = rfckt.txline('LineLength', 0.02, 'PV', 2e8);
casc = rfckt.cascade('Ckts', {tline, amp, tline});
freq = linspace(1e9, 3e9, 201);
analyze(casc, freq);
plot(casc, 'S21', 'dB');
grid on

f = 1e9;
lam = physconst('LightSpeed')/f;
d = dipole('Length', 0.48*lam, 'Width', lam/200);
show(d)
figure, pattern(d, f)
Z = impedance(d, f);
fprintf('Z = %.1f %+.1fj ohm\n', real(Z), imag(Z));
figure, impedance(d, linspace(0.7e9, 1.3e9, 51));

f0 = 2.45e9;
p = design(patchMicrostrip, f0);
p.Substrate = dielectric('FR4');
show(p)
freq = linspace(2.2e9, 2.7e9, 101);
S = sparameters(p, freq, 50);
figure, rfplot(S, 1, 1); grid on
figure, pattern(p, f0)
fprintf('Peak gain: %.2f dBi\n', max(pattern(p, f0, 0, 0:1:180)));

f = 1e9;
lam = physconst('LightSpeed')/f;
arr = linearArray('Element', dipole('Length', 0.48*lam, 'Width', lam/200), ...
    'NumElements', 8, 'ElementSpacing', lam/2);
arr.AmplitudeTaper = taylorwin(8)';
show(arr)
figure, pattern(arr, f, 0, 0:1:359)
steer = -(0:7) * 360 * 0.5 * sind(30);
arr.PhaseShift = steer;
figure, pattern(arr, f, 0, 0:1:359)

f0 = 5.8e9;
ant1 = design(dipole, f0);
ant2 = design(patchMicrostrip, f0);
ant3 = design(helix, f0);
fprintf('Dipole length: %.2f mm\n', ant1.Length*1000);
fprintf('Patch: %.2f x %.2f mm\n', ant2.Length*1000, ant2.Width*1000);
show(ant2)
figure, pattern(ant2, f0)

f = 2.4e9;
ant = design(patchMicrostrip, f);
figure, pattern(ant, f)                                  % 3-D
figure, pattern(ant, f, 0, 0:1:360)                      % elevation cut
figure, pattern(ant, f, 0:1:360, 0, 'CoordinateSystem', 'rectangular')
[D, az, el] = pattern(ant, f, 0:5:360, -90:5:90);
fprintf('Peak directivity: %.2f dBi\n', max(D(:)));

lam = physconst('LightSpeed')/1e9;
d = dipole('Length', 0.5*lam, 'Width', lam/200);
freq = linspace(0.7e9, 1.3e9, 121);
Z = impedance(d, freq);
plot(freq/1e9, real(Z), freq/1e9, imag(Z)); grid on
legend('R','X'); xlabel('GHz'); ylabel('Ohm')
[~, idx] = min(abs(imag(Z)));
fprintf('Resonance at %.3f GHz, R = %.1f ohm\n', freq(idx)/1e9, real(Z(idx)));

ant = design(patchMicrostrip, 2.4e9);
ant.Substrate = dielectric('FR4');
show(ant)
view(45, 30)
figure
m = mesh(ant, 'MaxEdgeLength', 0.005);
fprintf('%d triangles in the mesh\n', size(m.Elements, 2));
